interactions.sample_code:
function partition(A, p, r) {
  const x = pivot();            // x = A[r]
  let i = p - 1;
  setI(i);                      // ≤ x region is empty
  for (let j = p; j < r; j++) {
    setJ(j);
    if (lessEq(j)) {            // A[j] ≤ x
      i = i + 1;
      setI(i);
      swap(i, j);               // move it into the ≤ x region
      note('A[j] ≤ x: grow ≤ x region, both bars advance');
    } else {
      note('A[j] > x: only j advances, > x region grows');
    }
  }
  swap(i + 1, r);               // put the pivot between the regions
  setI(i + 1);
  return i + 1;
}

